import{_ as o,C as r,o as d,c,a6 as i,E as n,j as t,a as s}from"./chunks/framework.Bd7kzaCy.js";const f=JSON.parse('{"title":"第四部分　经验问题、结果合同与条件形式命题","description":"","frontmatter":{"title":"第四部分　经验问题、结果合同与条件形式命题"},"headers":[],"relativePath":"theory/part-04.md","filePath":"theory/part-04.md"}'),p={name:"theory/part-04.md"};function l(_,e,h,u,G,b){const a=r("SectionLesson");return d(),c("div",null,[e[0]||(e[0]=i("",1)),n(a,{section:"4.5"}),e[1]||(e[1]=t("div",{class:"theory-source"},[t("h2",{id:"section-4-6",tabindex:"-1"},[s("4.6　G4 表示闭合与对象或干预转换 "),t("a",{class:"header-anchor",href:"#section-4-6","aria-label":'Permalink to "4.6　G4 表示闭合与对象或干预转换 {#section-4-6}"'},"​")]),t("p",null,"命题：G4必须在结果出现前唯一预选一个子型及该子型的一个成功判据：G4a闭合失败可检验被排除尺度变量在给定目标尺度保留变量后的条件增量信息、条件预测增益或条件干预增益；G4b对象或干预转换可检验尺度变换M与对象动力或干预的非交换、目标映射不满足预冻结K、有效关系改变或干预响应改变；只有预选判据超过预定阈值或容差，才支持对应实例。"),t("p",null,"G4a 与 G4b 回答不同问题。G4a 允许的成功判据是 conditional_information_gain、conditional_predictive_gain、conditional_intervention_gain；每个实例只能预选其中一个。其零模型是：按预选判据，被排除尺度变量在保留变量条件下不提供超过阈值的条件增量。G4b 允许的成功判据是 object_dynamics_non_commutation、intervention_non_commutation、identity_criterion_violation、effective_relation_change、intervention_response_change；每个实例同样只能预选其中一个。零模型也只按被选项书写：对象动力可交换、干预可交换、目标映射满足预冻结 K、有效关系未超容差，或干预响应未超容差，不得把五项合成一个析取兜底。"),t("p",null,"一般相关、无条件耦合、相似叙述和同尺度遗漏变量都不足以支持 G4。结果前未唯一预选子型与成功判据，或 D3/E5 映射、比较模型、正向阈值、null_decision_rule、功效或灵敏度门与容差未冻结，实例暂停。正向判据通过时，G4a 只登记预注册变量、指标、尺度和窗口内的闭合失败，G4b 只登记预注册映射、K、尺度和窗口内的预选转换候选。正向判据未通过，默认只记 G4 未获支持或未决；只有零结论规则中的等价性或充分性检验、功效或灵敏度门及容差实际通过，G4a 才可登记判据限定闭合，G4b 才可登记未发现该预选转换。单纯“未显著”或未过正向阈值，不能直接登记闭合、对象未转换或干预等价。未选判据不得参与救援或反驳。通过 G4 也不表示高尺度更真、更重要或拥有更大处置权。"),t("p",null,"G4对闭合与非闭合保持对称的研究兴趣。按照登记的检验支持限定闭合，可以说明一个简洁表示在当前任务中已经足够；检出非闭合，说明需要修正表示、任务或操作范围。supported与null_supported只是相对预选事实断言的证据状态，不是方法好坏或理论进步的排名。"),t("p",null,"G4的比较必须指明闭合是相对于哪些目标、期限、环境和允许操作。常态预测充分不保证新增干预下仍充分；同一宏观状态可能因被折叠的组成不同而对同一操作作出不同反应。发现不足后，可以增补必要变量、保留组成或历史、限制动作集合、缩短期限或收窄用途，不必恢复全部微观细节。闭合成立也可以是有效宏观描述的成功结果；涌现、聚合、同尺度遗漏和跨边界传导，不以G4闭合失败为普遍必要条件。"),t("p",null,"干预充分性示例：两个微观状态A₁、A₂在自然演化中进入B的概率都为0.2，因此把它们合成A可能对这一预测任务充分。某个干预下，二者进入B的概率分别为0.8、0.1，宏观干预结果便取决于A₁的份额p，概率为0.1+0.7p。此时可以尝试只补入p，而不是恢复全部微观细节。该教学构造区别预测闭合与干预闭合，并不证明现实系统一定采取这些数值。〔研究05.06〕")],-1)),n(a,{section:"4.6"}),e[2]||(e[2]=i("",1))])}const C=o(p,[["render",l]]);export{f as __pageData,C as default};
